/**
 * 各数据模块共用的常量与工具。
 * 这些内容原本在 7 个 *Get.vue 里各抄了一份。
 */

/** 数据与静态资源的前缀（部署在子路径时改这里即可） */
export const NET = ''

/** 难度配色 */
export const DIF_COLORS = {
  EZ: '#0D9A28',
  HD: '#0175B8',
  IN: '#CF1313',
  AT: '#383838',
  SP: '#383838',
  LY: '#383838'
}

export const DEFAULT_DIF_COLOR = '#383838'

export function difColor(dif) {
  return DIF_COLORS[dif] || DEFAULT_DIF_COLOR
}

/** 低分辨率曲绘 */
export function illLowPath(songId) {
  return `${NET}/assets/illLow/${songId}.png`
}

/** 高分辨率曲绘 */
export function illPath(songId) {
  return `${NET}/assets/ill/${songId}.png`
}

/** 给一首歌补上封面地址与各难度配色（就地修改） */
export function decorateSong(song, songId, diffs = ['EZ', 'HD', 'IN', 'AT']) {
  if (!song || typeof song !== 'object') return song
  song.cover = illLowPath(songId)
  for (const dif of diffs) {
    if (song[dif]) song[dif].color = difColor(dif)
  }
  return song
}

/** 给「歌曲键名 → 歌曲」结构的整份数据补封面与配色 */
export function decorateSongMap(data, diffs = ['EZ', 'HD', 'IN', 'AT']) {
  if (!data || typeof data !== 'object') return data
  for (const songId of Object.keys(data)) {
    decorateSong(data[songId], songId, diffs)
  }
  return data
}

/** 给「分组 → 歌曲键名 → 歌曲」结构的整份数据补封面与配色 */
export function decorateGroupedSongMap(data, diffs = ['EZ', 'HD', 'IN', 'AT']) {
  if (!data || typeof data !== 'object') return data
  for (const groupKey of Object.keys(data)) {
    decorateSongMap(data[groupKey], diffs)
  }
  return data
}
